  "Mkt3L10n.DataFormPanel.This_option_allows_control_how_filters_separated": "<p>Esta opção permite que você controle como os filtros são usados. Somente os filtros são afetados — todos os gatilhos serão aplicados separadamente.</p><p>Insira os números de filtro separadamente por \"e\" e \"ou\".</p><ul><li>1 e 2 e 3</li><li>1 ou 2 ou 3</li></ul><p>A mistura de \"e\" e \"ou\" necessita de parênteses para que sua intenção fique clara. Por exemplo, \"1 ou 2 e 3\" deve ser escritos como um dos seguintes:</p><ul><li>1 e (2 ou 3)</li><li>(1 e 2) ou 3</li></ul><p>A lógica mais complicada pode exigir parênteses aninhados.</p><ul><li>(1 e 2) ou (3 e 4)</li><li>1 e (2 ou (3 e 4))</li></ul><br /><p><img src=\"/images/icons16/sign_warning.png\" class=\"mki16-p\" /> Verifique suas regras depois de inserir, excluir ou reordenar.</p>",
